{"cards": [{"node_code": "N_5fbb9b22d2433853", "definition": "研究非线性电路元件（如二极管、晶体管、非线性电阻）的静态伏安特性、工作点确定及小信号线性化等效电路模型，旨在简化局部动态分析。", "boundary": "本节点聚焦于非线性元件的静态特性描述及在工作点附近的线性近似方法。包括直流工作点计算、小信号模型推导（如gm、rds）及基于线性化模型的局部频率或时域响应分析。若内容涉及远离工作点的大信号非线性动态演化、混沌现象或全局稳定性分析，则不属于本节点。", "includes": ["非线性元件的直流工作点（Q点）计算与稳定性分析", "小信号等效电路模型（如混合π模型）的推导与应用", "基于线性化模型的局部增益、阻抗及频率响应分析"], "excludes": ["远离工作点的大信号非线性动态行为或混沌现象", "非线性元件内部载流子输运的物理机制或半导体工艺"], "sibling_distinctions": [{"other_code": "N_dacb9dbafc14c2b2", "rule": "本节点侧重局部线性化近似及静态特性；兄弟节点侧重全局非线性动态行为、分岔及混沌现象。"}, {"other_code": "N_3a1f24821fcd77d8", "rule": "本节点涵盖通用非线性元件（含半导体）；兄弟节点特指铁磁材料引起的非线性电感及磁滞效应。"}], "cross_boundary_rule": "若分析仅在工作点附近进行线性化求解，归入本节点；若需考虑大信号摆动或全局非线性动态，归入状态空间分岔节点。"}, {"node_code": "N_dacb9dbafc14c2b2", "definition": "研究非线性电路在状态空间描述下的动态行为，包括平衡点稳定性、分岔现象、极限环振荡及混沌效应，以蔡氏电路为典型代表。", "boundary": "本节点聚焦于非线性系统的全局动态特性及复杂行为。包括状态空间方程建立、雅可比矩阵稳定性分析、分岔图绘制、李雅普诺夫指数计算及混沌电路（如蔡氏电路、Chua's circuit）的仿真与实验验证。若内容仅涉及小信号线性化或静态工作点分析，则不属于本节点。", "includes": ["非线性电路的状态空间建模与平衡点稳定性分析", "分岔理论、极限环振荡及混沌现象的数学描述", "蔡氏电路等典型混沌电路的结构、参数及动力学特性"], "excludes": ["线性电路的叠加原理或频域响应分析", "非线性元件的静态伏安特性或小信号线性化模型"], "sibling_distinctions": [{"other_code": "N_5fbb9b22d2433853", "rule": "本节点研究全局非线性动态及混沌；兄弟节点研究局部线性化及静态特性。"}, {"other_code": "N_3a1f24821fcd77d8", "rule": "本节点涵盖通用非线性动态系统；兄弟节点特指铁磁非线性引起的谐振与磁滞建模。"}], "cross_boundary_rule": "若重点在于系统是否进入混沌或分岔路径，归入本节点；若重点在于特定铁磁元件的非线性参数建模，归入铁磁谐振节点。"}, {"node_code": "N_3a1f24821fcd77d8", "definition": "研究含铁磁材料电感元件的电路非线性特性，包括磁滞回线建模、铁磁谐振现象及其在电力系统中的影响与抑制方法。", "boundary": "本节点聚焦于铁磁材料非线性磁化特性对电路行为的影响。包括磁滞回线的数学模型（如Jiles-Atherton模型）、铁磁谐振（如电压互感器谐振）的机理分析、仿真及工程抑制措施。若内容涉及非铁磁材料的非线性或通用混沌电路，则不属于本节点。", "includes": ["铁磁材料磁滞回线的数学建模与参数辨识", "铁磁谐振（如TVR谐振）的机理、仿真及工程抑制", "非线性电感在电力系统暂态过程中的动态行为"], "excludes": ["通用非线性电阻或半导体器件的伏安特性分析", "非铁磁材料（如压电、压阻）的非线性效应"], "sibling_distinctions": [{"other_code": "N_5fbb9b22d2433853", "rule": "本节点特指铁磁非线性；兄弟节点涵盖通用非线性元件（含半导体）。"}, {"other_code": "N_dacb9dbafc14c2b2", "rule": "本节点侧重铁磁谐振这一特定工程现象；兄弟节点侧重通用混沌与分岔理论。"}], "cross_boundary_rule": "若分析核心是铁磁材料的磁滞特性及其引起的谐振，归入本节点；若铁磁元件仅作为混沌电路中的一个非线性元件且重点在于混沌动力学，可归入状态空间分岔节点。"}]}
